    # three-cell L groups, assigned by orientation/position as in demonstrations
    groups=[(3,[(1,0),(1,1),(2,1)]),(2,[(2,1),(2,2),(3,2)]),(4,[(1,4),(2,4),(2,5)]),(2,[(2,3),(3,2),(3,3)]),(3,[(2,0),(2,1),(3,1)]),(4,[(0,2),(1,2),(1,3)])]
